def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    cd = sum(1 for m, o in history if m == 'C' and o == 'D')
    opp_def = sum(1 for _, o in history if o == 'D')
    my_def = sum(1 for m, _ in history if m == 'D')

    if cd > 2:
        return 'D'

    if opp_def == 0:
        if n < 10:
            return 'C'
        return 'D'

    last_my, last_opp = history[-1]

    if last_opp == 'D':
        consec_opp = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                consec_opp += 1
            else:
                break
        consec_my = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D':
                consec_my += 1
            else:
                break

        if consec_opp >= 4:
            if last_my == 'C':
                return 'D'
            else:
                return 'C'
        if consec_opp >= 2:
            if consec_my >= 2:
                return 'C'
            else:
                return 'D'
        else:
            return 'C'
    else:
        for i in range(n - 2, -1, -1):
            if history[i][0] == 'D':
                if i + 1 < n:
                    resp = history[i + 1][1]
                    if resp == 'C':
                        return 'D'
                    else:
                        return 'C'
                break
        return 'C'
